// ─── File: PushPipelineDemo.java ───
// Push pipeline: progressive generation → queue → batched, rate-limited, idempotent delivery → DLQ + tracking.
// Each class below would be its own file in a real project.
package com.bank.push;

import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class PushPipelineDemo {

    private static final Logger log = Logger.getLogger("Push");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        BlockingQueue<String[]> queue = new LinkedBlockingQueue<>();   // the shock absorber (Kafka in prod)
        PushProvider provider = new PushProvider();
        DeliveryTracker tracker = new DeliveryTracker();

        // GENERATE progressively: a campaign to many customers (incl. Rajesh, Priya).
        CampaignGenerator gen = new CampaignGenerator(queue);
        gen.generate("SCHEME-2026", List.of("RAJESH-tok", "PRIYA-tok", "BAD-tok",
                "C4-tok", "C5-tok", "C6-tok"));   // BAD-tok simulates an invalid device

        // DELIVER: a worker drains the queue, batches, rate-limits, idempotently sends.
        DeliveryWorker worker = new DeliveryWorker(queue, provider, tracker);
        worker.runUntilEmpty();

        // TRACK: simulated async provider callbacks update delivery state.
        tracker.applyCallback("RAJESH-tok", "DELIVERED");
        tracker.applyCallback("PRIYA-tok", "OPENED");
        tracker.report();
    }
}

// ─── generate/CampaignGenerator.java ───  progressive, paged generation
class CampaignGenerator {
    private static final Logger log = Logger.getLogger("Push");
    private final BlockingQueue<String[]> queue;
    CampaignGenerator(BlockingQueue<String[]> queue) { this.queue = queue; }

    void generate(String campaignId, List<String> tokens) {
        int page = 3;                                   // page-size (10k in prod) — never all at once
        for (int i = 0; i < tokens.size(); i += page) {
            List<String> chunk = tokens.subList(i, Math.min(i + page, tokens.size()));
            for (String tok : chunk) {
                String notifId = campaignId + ":" + tok;    // UNIQUE notification id (idempotency)
                queue.offer(new String[]{ notifId, tok, "New scheme available" });
            }
            log.info(() -> "generated page of " + chunk.size() + " jobs (progressive)");
        }
    }
}

// ─── deliver/DeliveryWorker.java ───  batch + rate-limit + idempotent + retry → DLQ
class DeliveryWorker {
    private static final Logger log = Logger.getLogger("Push");
    private final BlockingQueue<String[]> queue;
    private final PushProvider provider;
    private final DeliveryTracker tracker;
    private final Set<String> sent = ConcurrentHashMap.newKeySet();   // idempotency store
    private long tokensAvail = 2000; // token bucket (per-sec) — stays within provider rate

    DeliveryWorker(BlockingQueue<String[]> q, PushProvider p, DeliveryTracker t) {
        queue = q; provider = p; tracker = t;
    }

    void runUntilEmpty() {
        List<String[]> batch = new ArrayList<>();
        String[] job;
        while ((job = queue.poll()) != null) {
            if (sent.contains(job[0])) { log.warning("idempotent skip " + job[0]); continue; } // no double-send
            batch.add(job);
            if (batch.size() >= 500 || queue.isEmpty()) { flush(batch); batch.clear(); }  // batch API
        }
    }

    private void flush(List<String[]> batch) {
        if (batch.isEmpty()) return;
        if (tokensAvail-- <= 0) { log.warning("rate-limited, waiting for token refill"); tokensAvail = 2000; }
        // ONE provider request for the whole batch (1 request → N notifications)
        Map<String, Boolean> results = provider.sendBatch(batch);
        for (String[] j : batch) {
            String notifId = j[0], token = j[1];
            if (results.getOrDefault(token, false)) {
                sent.add(notifId); tracker.mark(token, "SENT");
            } else {
                retryOrDlq(j);                                  // per-token failure handling
            }
        }
        log.info(() -> "batch of " + batch.size() + " sent via provider (1 request)");
    }

    private void retryOrDlq(String[] job) {
        for (int attempt = 1; attempt <= 3; attempt++) {
            if (provider.sendOne(job[1])) { sent.add(job[0]); tracker.mark(job[1], "SENT"); return; }
        }
        tracker.mark(job[1], "FAILED → DLQ");                   // permanent fail → dead-letter queue
        log.severe(() -> "DLQ: " + job[0] + " (invalid/unreachable token " + job[1] + ")");
    }
}

// ─── provider/PushProvider.java ───  simulates Firebase batch + per-token results
class PushProvider {
    Map<String, Boolean> sendBatch(List<String[]> batch) {
        Map<String, Boolean> res = new HashMap<>();
        for (String[] j : batch) res.put(j[1], !j[1].startsWith("BAD"));  // BAD-tok fails
        return res;
    }
    boolean sendOne(String token) { return !token.startsWith("BAD"); }
}

// ─── track/DeliveryTracker.java ───  state from async callbacks
class DeliveryTracker {
    private static final Logger log = Logger.getLogger("Push");
    private final Map<String, String> state = new ConcurrentHashMap<>();
    void mark(String token, String s) { state.put(token, s); }
    void applyCallback(String token, String s) { state.put(token, s); }     // async provider webhook
    void report() {
        log.info(() -> "delivery state = " + state);
        long delivered = state.values().stream().filter(v -> v.contains("DELIVERED") || v.contains("OPENED") || v.equals("SENT")).count();
        log.info(() -> "succeeded=" + delivered + " / " + state.size());
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
